// ===========================================================================
// Section: src/error.rs — Error type (hand-written)
// ===========================================================================

// Error types for the libfuse schema crate.

/// Errors returned by the FUSE operation traits and the session API.
///
/// Filesystem callbacks in C return `0` or `-errno`; in this crate
/// that becomes `Result<_, FuseError>`, with the errno carried in
/// [`FuseError::Errno`].
#[derive(Debug, Error)]
pub enum FuseError {
    /// An errno-style failure (`-errno` from a C callback).
    ///
    /// The code is the positive errno value (e.g. `2` for `ENOENT`).
    #[error("fuse error: errno {code}")]
    Errno {
        /// Positive errno value.
        code: i32,
    },

    /// The operation is not implemented (`ENOSYS`).
    ///
    /// This is the default result of every trait method: a filesystem
    /// only implements the operations it supports, exactly as a NULL
    /// function pointer in `struct fuse_operations` means "not
    /// implemented" in C.
    #[error("operation not implemented (ENOSYS)")]
    NotImplemented,

    /// The requested operation is not supported by this backend.
    #[error("unsupported operation: {0}")]
    Unsupported(String),

    /// Invalid argument or malformed input.
    #[error("invalid argument: {0}")]
    InvalidArgument(String),

    /// The libfuse C library is not linked into this process.
    ///
    /// This crate is the schema/type layer only; the session and
    /// mount entry points (`fuse_main`, `fuse_session_new`, ...)
    /// need an FFI backend that links libfuse. Implement
    /// [`FuseApi`] on such a backend.
    #[error("libfuse is not linked: {0}")]
    NotLinked(String),

    /// JSON (de)serialization failure.
    #[error("serialization error: {0}")]
    Serde(#[from] serde_json::Error),
}

impl FuseError {
    /// Build an errno error from a C-style negative return value.
    ///
    /// `ret` is the value a C callback would return: `0` on success,
    /// `-errno` on failure. Returns `Ok(())` for `0`.
    pub fn from_c_return(ret: i32) -> Result<(), Self> {
        if ret == 0 {
            Ok(())
        } else {
            Err(Self::Errno { code: -ret })
        }
    }

    /// Build an errno error from a positive errno value.
    pub fn errno(code: i32) -> Self {
        Self::Errno { code }
    }
}

// ===========================================================================
// Section: src/coerce.rs — String coercion newtypes (hand-written, from incus_device.rs)
// ===========================================================================

// String-coerced values, following the `incus_device.rs` StrBool/StrInt
// pattern: a boolean or integer carried on the wire as a string.
//
// The newtypes deserialize from either a JSON string or a native value
// and ALWAYS serialize back to a string, so round-tripping through the
// string form is lossless. They are used where the C API carries the
// value as a string — the FUSE `-o` mount options (`FuseMountOptions`)
// — never where the wire form is numeric.
//
// Fail-closed deviation from the reference vocabulary, per the
// no-drift principle: the reference accepts the aliases `"yes"` /
// `"on"` / `"no"` / `"off"` and the empty string (as false). This crate
// accepts only the exact wire forms — `"true"` / `"false"` (and
// `"1"` / `"0"`) for booleans, a strict decimal string for integers.
// An alias or an empty string is malformed input, not a default value,
// and is an error. `StrInt` also rejects a `u64` that does not fit in
// `i64` (the reference's `as` cast would silently wrap) and rejects
// non-integer JSON numbers.

/// A boolean carried on the wire as the string `"true"` / `"false"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StrBool(pub bool);

impl Serialize for StrBool {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(if self.0 { "true" } else { "false" })
    }
}

impl<'de> Deserialize<'de> for StrBool {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl serde::de::Visitor<'_> for V {
            type Value = StrBool;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("a boolean or a \"true\"/\"false\" string")
            }
            fn visit_bool<E: serde::de::Error>(self, v: bool) -> Result<StrBool, E> {
                Ok(StrBool(v))
            }
            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<StrBool, E> {
                match v {
                    "true" | "1" => Ok(StrBool(true)),
                    "false" | "0" => Ok(StrBool(false)),
                    other => Err(E::custom(format!("invalid boolean string: {other}"))),
                }
            }
        }
        d.deserialize_any(V)
    }
}

/// An integer carried on the wire as a decimal string (e.g. `"0"`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StrInt(pub i64);

impl Serialize for StrInt {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&self.0.to_string())
    }
}

impl<'de> Deserialize<'de> for StrInt {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl serde::de::Visitor<'_> for V {
            type Value = StrInt;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("an integer or an integer-like string")
            }
            fn visit_i64<E: serde::de::Error>(self, v: i64) -> Result<StrInt, E> {
                Ok(StrInt(v))
            }
            fn visit_u64<E: serde::de::Error>(self, v: u64) -> Result<StrInt, E> {
                i64::try_from(v)
                    .map(StrInt)
                    .map_err(|_| E::custom(format!("integer string out of range: {v}")))
            }
            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<StrInt, E> {
                v.trim()
                    .parse::<i64>()
                    .map(StrInt)
                    .map_err(|_| E::custom(format!("invalid integer string: {v}")))
            }
        }
        d.deserialize_any(V)
    }
}

#[cfg(test)]
mod coerce_tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn str_bool_accepts_only_exact_wire_forms() {
        for (value, expected) in [
            (json!("true"), true),
            (json!("false"), false),
            (json!("1"), true),
            (json!("0"), false),
            (json!(true), true),
            (json!(false), false),
        ] {
            let parsed: StrBool = serde_json::from_value(value).unwrap();
            assert_eq!(parsed.0, expected);
        }
        // Aliases and the empty string are malformed input, not defaults.
        for bad in ["yes", "on", "no", "off", "", "TRUE", "2", "t"] {
            assert!(
                serde_json::from_value::<StrBool>(json!(bad)).is_err(),
                "{bad:?} must fail closed"
            );
        }
        // A JSON number is not a boolean.
        assert!(serde_json::from_value::<StrBool>(json!(1)).is_err());
        // Always serializes back to a string.
        assert_eq!(serde_json::to_value(StrBool(true)).unwrap(), json!("true"));
        assert_eq!(serde_json::to_value(StrBool(false)).unwrap(), json!("false"));
    }

    #[test]
    fn str_int_accepts_only_strict_forms() {
        for (value, expected) in [
            (json!("42"), 42),
            (json!("-7"), -7),
            (json!("0"), 0),
            (json!(42), 42),
            (json!(-7), -7),
        ] {
            let parsed: StrInt = serde_json::from_value(value).unwrap();
            assert_eq!(parsed.0, expected);
        }
        for bad in ["abc", "", "1.5", "0x10"] {
            assert!(
                serde_json::from_value::<StrInt>(json!(bad)).is_err(),
                "{bad:?} must fail closed"
            );
        }
        // Non-integer JSON numbers and out-of-range u64 fail, never wrap.
        assert!(serde_json::from_value::<StrInt>(json!(1.5)).is_err());
        assert!(serde_json::from_value::<StrInt>(json!(u64::MAX)).is_err());
        assert_eq!(serde_json::to_value(StrInt(42)).unwrap(), json!("42"));
        assert_eq!(serde_json::to_value(StrInt(-7)).unwrap(), json!("-7"));
    }
}

