/// `struct fuse_uring_cmd_req` — SQE command area (80 bytes).
///
/// The C struct ends in an anonymous union: either a bufpool
/// descriptor (`uaddr`, `len`, `reserved`) or, on zero-copy queues,
/// the entry's registered-buffer slot index. The union is modelled
/// as an enum so the two cases cannot be confused.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseUringCmdReq {
    pub flags: u64,
    /// Entry identifier for commits.
    pub commit_id: u64,
    /// Queue the command is for (queue index).
    pub qid: u16,
    pub padding: [u8; 6],
    pub payload: FuseUringCmdReqPayload,
}

/// The trailing union of `struct fuse_uring_cmd_req`.
///
/// Internally tagged (`type` discriminator), so schemars renders
/// it as a `oneOf` discriminated union.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum FuseUringCmdReqPayload {
    /// Bufpool descriptor: base address, length and reserved word.
    Bufpool { uaddr: u64, len: u32, reserved: u32 },
    /// Registered-buffer slot index (zero-copy queues only).
    EntZeroCopyBufIndex { index: u16 },
}

