// ===========================================================================
// Section: src/types/stat.rs — libc stat types (hand-written)
// ===========================================================================

// libc types the FUSE headers reference but do not define.
//
// `struct stat`, `struct statvfs`, `struct flock`, `struct timespec`
// and `struct statx` come from the system headers. They are modelled
// here with their Linux x86_64 field layout (the logical fields; the
// C structs also carry ABI padding, which has no schema meaning).
// `Statx` is bit-for-bit compatible with the kernel `fuse_statx`
// record, so it is an alias for [`FuseStatx`].

pub type Statx = FuseStatx;
/// `struct timespec` — a second + nanosecond timestamp.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct Timespec {
    /// Seconds.
    pub sec: i64,
    /// Nanoseconds within the second.
    pub nsec: i64,
}

/// `struct stat` (Linux x86_64) — file attributes as `getattr` fills them.
///
/// Only the logical fields are modelled; the C struct's ABI padding is
/// not part of the schema. `st_dev` and `st_blksize` are ignored by
/// libfuse, and `st_ino` is ignored unless the `use_ino` mount option
/// is given.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FileStat {
    /// Device ID of the device containing the file.
    pub st_dev: u64,
    /// Inode number.
    pub st_ino: u64,
    /// Number of hard links.
    pub st_nlink: u64,
    /// File type and mode (see `S_IFMT` / permission bits).
    pub st_mode: u32,
    /// User ID of the file owner.
    pub st_uid: u32,
    /// Group ID of the file owner.
    pub st_gid: u32,
    /// Device ID (if the file is a device).
    pub st_rdev: u64,
    /// Total size, in bytes.
    pub st_size: i64,
    /// Block size for filesystem I/O.
    pub st_blksize: i64,
    /// Number of 512-byte blocks allocated.
    pub st_blocks: i64,
    /// Time of last access, seconds.
    pub st_atime: i64,
    /// Time of last access, nanoseconds.
    pub st_atime_nsec: i64,
    /// Time of last modification, seconds.
    pub st_mtime: i64,
    /// Time of last modification, nanoseconds.
    pub st_mtime_nsec: i64,
    /// Time of last status change, seconds.
    pub st_ctime: i64,
    /// Time of last status change, nanoseconds.
    pub st_ctime_nsec: i64,
}

/// `struct statvfs` — filesystem statistics as `statfs` fills them.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct Statvfs {
    /// Filesystem block size.
    pub f_bsize: u64,
    /// Fragment size.
    pub f_frsize: u64,
    /// Size of the filesystem in `f_frsize` units.
    pub f_blocks: u64,
    /// Number of free blocks.
    pub f_bfree: u64,
    /// Number of free blocks for unprivileged users.
    pub f_bavail: u64,
    /// Number of inodes.
    pub f_files: u64,
    /// Number of free inodes.
    pub f_ffree: u64,
    /// Number of free inodes for unprivileged users.
    pub f_favail: u64,
    /// Filesystem ID.
    pub f_fsid: u64,
    /// Mount flags.
    pub f_flag: u64,
    /// Maximum filename length.
    pub f_namemax: u64,
}

/// `struct flock` — a POSIX file lock region (see `fcntl(2)`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct Flock {
    /// Lock type: `F_RDLCK`, `F_WRLCK` or `F_UNLCK`.
    pub l_type: i16,
    /// How to interpret `l_start`: `SEEK_SET`, `SEEK_CUR` or `SEEK_END`.
    pub l_whence: i16,
    /// Starting offset of the locked region.
    pub l_start: i64,
    /// Length of the locked region (0 = to end of file).
    pub l_len: i64,
    /// Process holding the lock (only meaningful for `F_GETLK` replies).
    pub l_pid: i32,
}

/// `struct iovec` — a scatter/gather buffer (pointer + length).
///
/// Pointers are modelled as raw addresses (`u64`); the buffer contents
/// themselves travel out of band.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct Iovec {
    /// Base address of the buffer.
    pub base: u64,
    /// Length of the buffer in bytes.
    pub len: u64,
}

// ===========================================================================
// Section: src/types/common.rs — Common library types (hand-written, from fuse_common.h)
// ===========================================================================

// Common types from `fuse_common.h`: file info, connection info,
// data buffers, loop configuration and capability flags.
//
// The capability flags (`FUSE_CAP_*`) are modelled as the newtype
// [`FuseCapabilities`] (a `u64` bitset with named constants) rather
// than bare integers, so `capable` / `want` / `capable_ext` /
// `want_ext` cannot be confused with other flag words. The legacy
// 32-bit `capable` / `want` fields of `struct fuse_conn_info` are
// kept as plain `u32` for ABI fidelity; use
// [`FuseConnInfo::capable_flags`] / [`FuseConnInfo::want_flags`] to
// read them as [`FuseCapabilities`].

/// Capability bits for `fuse_conn_info.capable` / `want` (and the
/// 64-bit `capable_ext` / `want_ext`).
///
/// A bitset: use `|` to combine, `&` to test. The constants mirror
/// the `FUSE_CAP_*` defines in `fuse_common.h`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
pub struct FuseCapabilities(pub u64);

impl FuseCapabilities {
    /// No capabilities.
    pub const NONE: Self = Self(0);
    /// Filesystem supports asynchronous read requests.
    pub const ASYNC_READ: Self = Self(1 << 0);
    /// Filesystem supports "remote" (POSIX) locking.
    pub const POSIX_LOCKS: Self = Self(1 << 1);
    /// Filesystem supports the `O_TRUNC` open flag.
    pub const ATOMIC_O_TRUNC: Self = Self(1 << 3);
    /// Filesystem supports lookups of "." and "..".
    pub const EXPORT_SUPPORT: Self = Self(1 << 4);
    /// Kernel should not apply the umask to the file mode on create.
    pub const DONT_MASK: Self = Self(1 << 6);
    /// libfuse should try to use `splice(2)` when writing to the device.
    pub const SPLICE_WRITE: Self = Self(1 << 7);
    /// libfuse should try to move pages instead of copying.
    pub const SPLICE_MOVE: Self = Self(1 << 8);
    /// libfuse should try to use `splice(2)` when reading from the device.
    pub const SPLICE_READ: Self = Self(1 << 9);
    /// `flock(2)` calls are emulated using POSIX locks.
    pub const FLOCK_LOCKS: Self = Self(1 << 10);
    /// Filesystem supports `ioctl` on directories.
    pub const IOCTL_DIR: Self = Self(1 << 11);
    /// Check attribute validity on every read.
    pub const AUTO_INVAL_DATA: Self = Self(1 << 12);
    /// Filesystem supports readdirplus.
    pub const READDIRPLUS: Self = Self(1 << 13);
    /// Filesystem supports adaptive readdirplus.
    pub const READDIRPLUS_AUTO: Self = Self(1 << 14);
    /// Filesystem supports asynchronous direct I/O submission.
    pub const ASYNC_DIO: Self = Self(1 << 15);
    /// Writeback caching should be enabled.
    pub const WRITEBACK_CACHE: Self = Self(1 << 16);
    /// Support for zero-message opens.
    pub const NO_OPEN_SUPPORT: Self = Self(1 << 17);
    /// Support for parallel directory operations.
    pub const PARALLEL_DIROPS: Self = Self(1 << 18);
    /// Support for POSIX ACLs.
    pub const POSIX_ACL: Self = Self(1 << 19);
    /// Filesystem unsets setuid/setgid bits on write/truncate/chown.
    pub const HANDLE_KILLPRIV: Self = Self(1 << 20);
    /// Filesystem unsets setuid/setgid/cap on write/truncate/chown (v2 rules).
    pub const HANDLE_KILLPRIV_V2: Self = Self(1 << 21);
    /// Kernel supports caching symlinks in its page cache.
    pub const CACHE_SYMLINKS: Self = Self(1 << 23);
    /// Support for zero-message opendirs.
    pub const NO_OPENDIR_SUPPORT: Self = Self(1 << 24);
    /// Invalidate cached pages only on explicit request.
    pub const EXPLICIT_INVAL_DATA: Self = Self(1 << 25);
    /// Dentries can be expired (rather than invalidated).
    pub const EXPIRE_ONLY: Self = Self(1 << 26);
    /// Extended `struct fuse_setxattr` is used by the kernel side.
    pub const SETXATTR_EXT: Self = Self(1 << 27);
    /// `MAP_SHARED` mmap is allowed for `FUSE_DIRECT_IO` files.
    pub const DIRECT_IO_ALLOW_MMAP: Self = Self(1 << 28);
    /// Passthrough mode for read/write operations.
    pub const PASSTHROUGH: Self = Self(1 << 29);
    /// Filesystem cannot handle NFS export.
    pub const NO_EXPORT_SUPPORT: Self = Self(1 << 30);
    /// io-uring between fuse-server and fuse-client.
    pub const OVER_IO_URING: Self = Self(1 << 31);
    /// Creation of idmapped mounts is allowed.
    pub const ALLOW_IDMAP: Self = Self(1 << 32);
    /// Security context is sent to file creation operations.
    pub const SECURITY_CTX: Self = Self(1 << 33);
    /// io-uring payload buffer pools are supported.
    pub const IO_URING_BUFPOOL: Self = Self(1 << 34);

    /// True if all bits of `other` are set in `self`.
    pub fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }

    /// The raw bitmask.
    pub fn bits(self) -> u64 {
        self.0
    }
}

impl BitOr for FuseCapabilities {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        Self(self.0 | rhs.0)
    }
}

impl BitAnd for FuseCapabilities {
    type Output = Self;
    fn bitand(self, rhs: Self) -> Self {
        Self(self.0 & rhs.0)
    }
}

impl Default for FuseCapabilities {
    fn default() -> Self {
        Self::NONE
    }
}

/// `FUSE_IOCTL_*` flags (see `fuse_common.h`).
pub mod ioctl_flags {
    /// 32-bit compat ioctl on a 64-bit machine.
    pub const COMPAT: u32 = 1 << 0;
    /// Not restricted to well-formed ioctls; retry allowed.
    pub const UNRESTRICTED: u32 = 1 << 1;
    /// Retry with new iovecs.
    pub const RETRY: u32 = 1 << 2;
    /// The ioctl targets a directory.
    pub const DIR: u32 = 1 << 4;
    /// Maximum of `in_iovecs + out_iovecs`.
    pub const MAX_IOV: u32 = 256;
}

/// `FUSE_BACKING_STACKED_*` values for
/// `FuseConnInfo::max_backing_stack_depth`.
pub mod backing_stack {
    /// Backing files cannot be on a stacked filesystem.
    pub const UNDER: u32 = 0;
    /// Backing files may be on a stacked filesystem.
    pub const OVER: u32 = 1;
}

/// `FUSE_CONN_FLAG_*` values — libfuse-side connection hints (not
/// negotiated with the kernel).
pub mod conn_flags {
    /// Replies are sent from the same thread that received requests.
    pub const SINGLE_ISSUER: u64 = 1;
    /// Disable fuse interrupt handling.
    pub const NO_INTERRUPT: u64 = 1 << 1;
}

/// `struct fuse_file_info` — information about an open file.
///
/// File handles are created by `open`, `opendir` and `create` and
/// closed by `release` / `releasedir`. The C bitfields are modelled
/// as individual `bool` fields; the reserved padding words are kept
/// as `u32` so the layout stays visible.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseFileInfo {
    /// Open flags. Available in `open()`, `release()` and `create()`.
    pub flags: i32,
    /// Set when a write was caused by a delayed write from the page cache.
    pub writepage: bool,
    /// Use direct I/O on this file.
    pub direct_io: bool,
    /// Cached data need not be invalidated when the file is closed.
    pub keep_cache: bool,
    /// Indicates a flush operation.
    pub flush: bool,
    /// The file is not seekable.
    pub nonseekable: bool,
    /// `flock` locks for this file should be released (only in `release()`).
    pub flock_release: bool,
    /// Enable caching of entries returned by `readdir()` (only in `opendir()`).
    pub cache_readdir: bool,
    /// Flush is not needed on close.
    pub noflush: bool,
    /// Allow parallel direct writes on this file.
    pub parallel_direct_writes: bool,
    /// Filesystem must remove setuid/setgid bits (KILLPRIV_V2).
    pub kill_suidgid: bool,
    /// The file has no position; implies `nonseekable` (pipe-like files).
    pub stream: bool,
    /// Padding, reserved for future use.
    pub padding: u32,
    /// Padding, reserved for future use.
    pub padding2: u32,
    /// Padding, reserved for future use.
    pub padding3: u32,
    /// File handle id, filled in by the filesystem in `create`/`open`/`opendir`.
    pub fh: u64,
    /// Lock owner id. Available in locking operations and flush.
    pub lock_owner: u64,
    /// Requested poll events (only in `poll()`).
    pub poll_events: u32,
    /// Passthrough backing file id (filled in by `create`/`open`).
    pub backing_id: i32,
    /// `struct fuse_file_info` API/ABI flags.
    pub compat_flags: u64,
    /// Reserved.
    pub reserved: [u64; 2],
}

impl Default for FuseFileInfo {
    fn default() -> Self {
        Self {
            flags: 0,
            writepage: false,
            direct_io: false,
            keep_cache: false,
            flush: false,
            nonseekable: false,
            flock_release: false,
            cache_readdir: false,
            noflush: false,
            parallel_direct_writes: false,
            kill_suidgid: false,
            stream: false,
            padding: 0,
            padding2: 0,
            padding3: 0,
            fh: 0,
            lock_owner: 0,
            poll_events: 0,
            backing_id: 0,
            compat_flags: 0,
            reserved: [0; 2],
        }
    }
}

/// `struct fuse_conn_info` — connection information, passed to `init()`.
///
/// Some fields are read-write: the filesystem may lower the values
/// the kernel proposes. `capable` / `want` are the legacy 32-bit
/// capability words; `capable_ext` / `want_ext` carry the full 64-bit
/// set (use [`FuseCapabilities`] with them).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseConnInfo {
    /// Major version of the protocol (read-only).
    pub proto_major: u32,
    /// Minor version of the protocol (read-only).
    pub proto_minor: u32,
    /// Maximum size of write requests.
    pub max_write: u32,
    /// Maximum size of read requests (0 = no limit).
    pub max_read: u32,
    /// Maximum readahead.
    pub max_readahead: u32,
    /// Capability flags the kernel supports (read-only, legacy 32-bit).
    pub capable: u32,
    /// Capability flags the filesystem wants (legacy 32-bit).
    pub want: u32,
    /// Maximum number of pending background requests.
    pub max_background: u32,
    /// Kernel congestion threshold parameter.
    pub congestion_threshold: u32,
    /// Timestamp granularity supported by the filesystem (power of 10;
    /// 1 = full nanosecond resolution).
    pub time_gran: u32,
    /// Maximum allowed stacking depth of backing files (see `backing_stack`).
    pub max_backing_stack_depth: u32,
    /// Disable `FUSE_INTERRUPT` requests.
    pub no_interrupt: bool,
    /// Replies to io-uring requests are sent from the receiving thread.
    pub io_uring_single_issuer: bool,
    /// Reserved bits for future use.
    pub padding: u32,
    /// Extended capability flags the kernel supports (read-only).
    pub capable_ext: u64,
    /// Extended capability flags the filesystem wants to enable.
    pub want_ext: u64,
    /// Request timeout in seconds (0 = none).
    pub request_timeout: u16,
    /// Reserved.
    pub reserved: [u16; 31],
}

impl FuseConnInfo {
    /// The kernel's capabilities as [`FuseCapabilities`].
    pub fn capable_flags(&self) -> FuseCapabilities {
        FuseCapabilities(self.capable_ext)
    }

    /// The filesystem's wanted capabilities as [`FuseCapabilities`].
    pub fn want_flags(&self) -> FuseCapabilities {
        FuseCapabilities(self.want_ext)
    }

    /// Request a capability (sets the bit in `want_ext`).
    pub fn want_capability(&mut self, cap: FuseCapabilities) {
        self.want_ext |= cap.0;
    }

    /// Drop a requested capability (clears the bit in `want_ext`).
    pub fn drop_capability(&mut self, cap: FuseCapabilities) {
        self.want_ext &= !cap.0;
    }
}

/// `enum fuse_buf_flags` — buffer flags for `struct fuse_buf`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[repr(u32)]
pub enum FuseBufFlags {
    /// No flags.
    None = 0,
    /// Buffer contains a file descriptor (`.fd` is valid, not `.mem`).
    IsFd = 1 << 1,
    /// Seek on the file descriptor (`.pos` is valid).
    FdSeek = 1 << 2,
    /// Retry the operation on the file descriptor until done.
    FdRetry = 1 << 3,
}

/// `enum fuse_buf_copy_flags` — flags for `fuse_buf_copy()`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[repr(u32)]
pub enum FuseBufCopyFlags {
    /// No flags.
    None = 0,
    /// Don't use `splice(2)`; always fall back to read/write.
    NoSplice = 1 << 1,
    /// Force `splice(2)`; return `-EINVAL` if unavailable.
    ForceSplice = 1 << 2,
    /// Try to move pages with splice instead of copying.
    SpliceMove = 1 << 3,
    /// Don't block on the pipe when copying with splice.
    SpliceNonblock = 1 << 4,
}

/// `struct fuse_buf` — a single data buffer.
///
/// Data may be supplied as a memory pointer or as a file descriptor.
/// Pointers are modelled as raw addresses (`u64`); the buffer
/// contents themselves travel out of band.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseBuf {
    /// Size of data in bytes.
    pub size: u64,
    /// Buffer flags.
    pub flags: FuseBufFlags,
    /// Memory address (`None` if `flags` contains `IsFd`).
    pub mem: Option<u64>,
    /// File descriptor (`None` unless `flags` contains `IsFd`).
    pub fd: Option<i32>,
    /// File position (only if `flags` contains `FdSeek`).
    pub pos: i64,
    /// Size of the memory pointer (only if internally allocated).
    pub mem_size: u64,
}

/// `struct fuse_bufvec` — a vector of data buffers.
///
/// The C struct has a flexible `buf[1]` array; here it is a plain
/// `Vec<FuseBuf>`. `idx` / `off` track the current read position.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseBufvec {
    /// The buffers.
    pub buf: Vec<FuseBuf>,
    /// Index of the current buffer within the array.
    pub idx: u64,
    /// Current offset within the current buffer.
    pub off: u64,
}

impl FuseBufvec {
    /// Total size of the data in the buffer vector.
    pub fn total_size(&self) -> u64 {
        self.buf.iter().map(|b| b.size).sum()
    }
}

/// `struct fuse_loop_config` — configuration for `fuse_loop_mt()` /
/// `fuse_session_loop_mt()` (API version < 3.12 shape; binary
/// compatible with the newer config).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseLoopConfig {
    /// Whether to use separate device fds for each thread.
    pub clone_fd: i32,
    /// Maximum idle worker threads before they are deleted (default 10;
    /// 0 = a new thread per operation).
    pub max_idle_threads: u32,
}

/// `struct libfuse_version` — the version a filesystem was compiled with.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct LibfuseVersion {
    /// Major version.
    pub major: u32,
    /// Minor version.
    pub minor: u32,
    /// Hotfix version.
    pub hotfix: u32,
    /// API version (`FUSE_MAKE_VERSION(major, minor)`).
    pub api_version: u32,
}

/// The libfuse version this crate's types were generated from.
pub const LIBFUSE_VERSION: LibfuseVersion = LibfuseVersion {
    major: 3,
    minor: 19,
    hotfix: 0,
    api_version: 319,
};

// ===========================================================================
// Section: src/types/highlevel.rs — High-level API types and FuseOperations (hand-written, from fuse.h)
// ===========================================================================

// High-level API types from `fuse.h`: configuration, request
// context, readdir flags and the `fuse_operations` callback table.
//
// The C callback table (`struct fuse_operations`, a struct of
// function pointers) is modelled as the [`FuseOperations`] trait:
// one typed method per operation, each defaulting to
// [`FuseError::NotImplemented`] — the exact equivalent of a NULL
// function pointer in C. A filesystem implements the trait; the FFI
// layer (not this crate) adapts the trait into the C table.
//
// Integer fields keep the C widths (`int32_t` -> `i32`, etc.).
// Pointers that carry no schema data (the `struct fuse *` handle,
// `private_data`, poll handles) are modelled as opaque `u64`
// handles, documented as such.


/// Opaque handle for `struct fuse *` (the high-level filesystem object).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
pub struct FuseHandle(pub u64);

/// Opaque handle for `struct fuse_pollhandle *`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
pub struct PollHandle(pub u64);

/// `enum fuse_readdir_flags` — flags passed to `readdir()`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[repr(u32)]
pub enum FuseReaddirFlags {
    /// Default behaviour.
    Defaults = 0,
    /// "Plus" mode: the kernel wants the inode cache prefilled.
    Plus = 1,
}

/// `enum fuse_fill_dir_flags` — flags passed to the `fuse_fill_dir_t`
/// filler callback.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[repr(u32)]
pub enum FuseFillDirFlags {
    /// Default behaviour.
    Defaults = 0,
    /// "Plus" mode: the entry's file attributes are valid.
    Plus = 1 << 1,
}

/// One directory entry as returned by `readdir()`.
///
/// The C API streams entries through the `fuse_fill_dir_t` filler
/// callback; here the entries are collected into a typed vector.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct DirEntry {
    /// File name of the directory entry.
    pub name: String,
    /// File attributes (`None` unless `FuseReaddirFlags::Plus` was honoured).
    pub stat: Option<FileStat>,
    /// Offset of the next entry (0 = seeking in directories unsupported).
    pub offset: i64,
}

/// Result of an `ioctl()` operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct IoctlResult {
    /// The ioctl's integer result value.
    pub result: i32,
    /// Output data produced by the ioctl.
    pub data: Vec<u8>,
}

/// `struct fuse_config` — configuration of the high-level API.
///
/// Initialized from the arguments passed to `fuse_new()` and passed
/// to the filesystem's `init()` handler. Integer fields keep the C
/// `int32_t` width; `0` means false for the boolean-valued ones.
/// New options must be appended at the end (ABI sensitive).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FuseConfig {
    /// If non-zero, `st_gid` of each file is overwritten with `gid`.
    pub set_gid: i32,
    /// Group id to force when `set_gid` is set.
    pub gid: u32,
    /// If non-zero, `st_uid` of each file is overwritten with `uid`.
    pub set_uid: i32,
    /// User id to force when `set_uid` is set.
    pub uid: u32,
    /// If non-zero, the file mode is overwritten with `umask`.
    pub set_mode: i32,
    /// Umask to force when `set_mode` is set.
    pub umask: u32,
    /// Timeout for directory entry caching, in seconds.
    pub entry_timeout: f64,
    /// Timeout for negative entries, in seconds.
    pub negative_timeout: f64,
    /// Timeout for attribute caching, in seconds.
    pub attr_timeout: f64,
    /// If non-zero, allow filesystem requests to be interrupted.
    pub intr: i32,
    /// Signal to send on interrupt (only if `intr` is set).
    pub intr_signal: i32,
    /// Remember inodes after they are removed (in seconds).
    pub remember: i32,
    /// If non-zero, remove files directly instead of renaming them.
    pub hard_remove: i32,
    /// If non-zero, use the `st_ino` field supplied by the filesystem.
    pub use_ino: i32,
    /// If non-zero, use the `st_ino` field in `readdir()`.
    pub readdir_ino: i32,
    /// If non-zero, use direct I/O.
    pub direct_io: i32,
    /// If non-zero, allow the kernel to cache file data.
    pub kernel_cache: i32,
    /// If non-zero, enable auto-caching.
    pub auto_cache: i32,
    /// If non-zero, `ac_attr_timeout` is set.
    pub ac_attr_timeout_set: i32,
    /// Timeout for auto-cache attribute caching, in seconds.
    pub ac_attr_timeout: f64,
    /// If non-zero, allow NULL path in some operations.
    pub nullpath_ok: i32,
    /// If non-zero, print help and exit.
    pub show_help: i32,
    /// Filesystem modules to load (comma-separated, `None` if unset).
    pub modules: Option<String>,
    /// If non-zero, enable debug output.
    pub debug: i32,
    /// File creation mask.
    pub fmask: u32,
    /// Directory creation mask.
    pub dmask: u32,
    /// If non-zero, don't flush on close of a read-only fd.
    pub no_rofd_flush: i32,
    /// If non-zero, allow parallel direct writes.
    pub parallel_direct_writes: i32,
    /// Option flags.
    pub flags: u32,
    /// Reserved for future use (fixed-size array of 48 in C; serde
    /// and schemars only support arrays up to length 32, so this is
    /// a `Vec` with the fixed length documented).
    pub reserved: Vec<u64>,
}

/// `struct fuse_context` — context of the request currently being
/// served (see `fuse_get_context()`).
///
/// The `fuse` handle and `private_data` are opaque pointers in C;
/// they are carried here as `u64` addresses (0 when not applicable).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseContext {
    /// Pointer to the fuse object (raw address).
    pub fuse: u64,
    /// User ID of the calling process.
    pub uid: u32,
    /// Group ID of the calling process.
    pub gid: u32,
    /// Process ID of the calling thread.
    pub pid: i32,
    /// Private filesystem data (raw address).
    pub private_data: u64,
    /// Umask of the calling process.
    pub umask: u32,
}

/// The high-level filesystem operations (`struct fuse_operations`).
///
/// One typed method per C callback. Every method has a default
/// implementation returning [`FuseError::NotImplemented`], so a
/// filesystem only implements the operations it supports — exactly
/// as a NULL function pointer means "not implemented" in C.
///
/// Return values follow the C convention: `Ok(())` is success,
/// `Err(FuseError::Errno { code })` is `-errno`. Methods that return
/// data in C (through an output buffer or a return value) return it
/// directly: `read` returns the bytes, `readlink` the target,
/// `readdir` the collected entries, `copy_file_range` the bytes
/// copied, `lseek` the resulting offset.
pub trait FuseOperations: Send {
    /// Get file attributes.
    fn getattr(
        &mut self,
        path: &str,
        stat: &mut FileStat,
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, stat, fi);
        Err(FuseError::NotImplemented)
    }

    /// Read the target of a symbolic link.
    fn readlink(&mut self, path: &str) -> Result<String, FuseError> {
        let _ = path;
        Err(FuseError::NotImplemented)
    }

    /// Create a file node.
    fn mknod(&mut self, path: &str, mode: u32, rdev: u64) -> Result<(), FuseError> {
        let _ = (path, mode, rdev);
        Err(FuseError::NotImplemented)
    }

    /// Create a directory.
    fn mkdir(&mut self, path: &str, mode: u32) -> Result<(), FuseError> {
        let _ = (path, mode);
        Err(FuseError::NotImplemented)
    }

    /// Remove a file.
    fn unlink(&mut self, path: &str) -> Result<(), FuseError> {
        let _ = path;
        Err(FuseError::NotImplemented)
    }

    /// Remove a directory.
    fn rmdir(&mut self, path: &str) -> Result<(), FuseError> {
        let _ = path;
        Err(FuseError::NotImplemented)
    }

    /// Create a symbolic link (`target` is what the link points at).
    fn symlink(&mut self, target: &str, link_path: &str) -> Result<(), FuseError> {
        let _ = (target, link_path);
        Err(FuseError::NotImplemented)
    }

    /// Rename a file. `flags` may be `RENAME_EXCHANGE` / `RENAME_NOREPLACE`.
    fn rename(&mut self, old_path: &str, new_path: &str, flags: u32) -> Result<(), FuseError> {
        let _ = (old_path, new_path, flags);
        Err(FuseError::NotImplemented)
    }

    /// Create a hard link.
    fn link(&mut self, old_path: &str, new_path: &str) -> Result<(), FuseError> {
        let _ = (old_path, new_path);
        Err(FuseError::NotImplemented)
    }

    /// Change the permission bits of a file.
    fn chmod(
        &mut self,
        path: &str,
        mode: u32,
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, mode, fi);
        Err(FuseError::NotImplemented)
    }

    /// Change the owner of a file.
    fn chown(
        &mut self,
        path: &str,
        uid: u32,
        gid: u32,
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, uid, gid, fi);
        Err(FuseError::NotImplemented)
    }

    /// Change the size of a file.
    fn truncate(
        &mut self,
        path: &str,
        size: i64,
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, size, fi);
        Err(FuseError::NotImplemented)
    }

    /// Open a file.
    fn open(&mut self, path: &str, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, fi);
        Err(FuseError::NotImplemented)
    }

    /// Read data from an open file. Returns the bytes read.
    fn read(
        &mut self,
        path: &str,
        size: usize,
        offset: i64,
        fi: &mut FuseFileInfo,
    ) -> Result<Vec<u8>, FuseError> {
        let _ = (path, size, offset, fi);
        Err(FuseError::NotImplemented)
    }

    /// Write data to an open file. Returns the number of bytes written.
    fn write(
        &mut self,
        path: &str,
        data: &[u8],
        offset: i64,
        fi: &mut FuseFileInfo,
    ) -> Result<usize, FuseError> {
        let _ = (path, data, offset, fi);
        Err(FuseError::NotImplemented)
    }

    /// Get filesystem statistics.
    fn statfs(&mut self, path: &str, stat: &mut Statvfs) -> Result<(), FuseError> {
        let _ = (path, stat);
        Err(FuseError::NotImplemented)
    }

    /// Possibly flush cached data on `close()`.
    fn flush(&mut self, path: &str, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, fi);
        Err(FuseError::NotImplemented)
    }

    /// Release an open file (last close of the file handle).
    fn release(&mut self, path: &str, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, fi);
        Err(FuseError::NotImplemented)
    }

    /// Synchronize file contents (`datasync` = data only, no metadata).
    fn fsync(&mut self, path: &str, datasync: bool, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, datasync, fi);
        Err(FuseError::NotImplemented)
    }

    /// Set an extended attribute.
    fn setxattr(
        &mut self,
        path: &str,
        name: &str,
        value: &[u8],
        flags: i32,
    ) -> Result<(), FuseError> {
        let _ = (path, name, value, flags);
        Err(FuseError::NotImplemented)
    }

    /// Get an extended attribute. `size` is the caller's buffer size;
    /// a larger value than the attribute is an error in C, here the
    /// full value is returned.
    fn getxattr(&mut self, path: &str, name: &str, size: usize) -> Result<Vec<u8>, FuseError> {
        let _ = (path, name, size);
        Err(FuseError::NotImplemented)
    }

    /// List extended attributes (names, without values).
    fn listxattr(&mut self, path: &str, size: usize) -> Result<Vec<String>, FuseError> {
        let _ = (path, size);
        Err(FuseError::NotImplemented)
    }

    /// Remove an extended attribute.
    fn removexattr(&mut self, path: &str, name: &str) -> Result<(), FuseError> {
        let _ = (path, name);
        Err(FuseError::NotImplemented)
    }

    /// Open a directory.
    fn opendir(&mut self, path: &str, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, fi);
        Err(FuseError::NotImplemented)
    }

    /// Read directory entries starting at `offset`. Returns the
    /// collected entries (the C filler callback is folded into this
    /// return value).
    fn readdir(
        &mut self,
        path: &str,
        offset: i64,
        fi: &mut FuseFileInfo,
        flags: FuseReaddirFlags,
    ) -> Result<Vec<DirEntry>, FuseError> {
        let _ = (path, offset, fi, flags);
        Err(FuseError::NotImplemented)
    }

    /// Release an open directory.
    fn releasedir(&mut self, path: &str, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, fi);
        Err(FuseError::NotImplemented)
    }

    /// Synchronize directory contents.
    fn fsyncdir(&mut self, path: &str, datasync: bool, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, datasync, fi);
        Err(FuseError::NotImplemented)
    }

    /// Initialize the filesystem. Returns the private-data handle
    /// (0 = none) that is passed back to `destroy()`.
    fn init(&mut self, conn: &mut FuseConnInfo, cfg: &mut FuseConfig) -> Result<u64, FuseError> {
        let _ = (conn, cfg);
        Ok(0)
    }

    /// Clean up the filesystem; receives the handle returned by `init()`.
    fn destroy(&mut self, private_data: u64) {
        let _ = private_data;
    }

    /// Check whether a file can be accessed with the given mode.
    fn access(&mut self, path: &str, mask: i32) -> Result<(), FuseError> {
        let _ = (path, mask);
        Err(FuseError::NotImplemented)
    }

    /// Create and open a file.
    fn create(&mut self, path: &str, mode: u32, fi: &mut FuseFileInfo) -> Result<(), FuseError> {
        let _ = (path, mode, fi);
        Err(FuseError::NotImplemented)
    }

    /// POSIX file locking (`F_GETLK` / `F_SETLK` / `F_SETLKW` via `cmd`).
    fn lock(
        &mut self,
        path: &str,
        fi: &mut FuseFileInfo,
        cmd: i32,
        lock: &mut Flock,
    ) -> Result<(), FuseError> {
        let _ = (path, fi, cmd, lock);
        Err(FuseError::NotImplemented)
    }

    /// Change the access and modification times of a file.
    fn utimens(
        &mut self,
        path: &str,
        times: [Timespec; 2],
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, times, fi);
        Err(FuseError::NotImplemented)
    }

    /// Map a block index within a file (`bmap`).
    fn bmap(&mut self, path: &str, blocksize: usize, idx: &mut u64) -> Result<(), FuseError> {
        let _ = (path, blocksize, idx);
        Err(FuseError::NotImplemented)
    }

    /// Control device (`ioctl`). `arg` is the raw ioctl argument,
    /// `data` the input buffer (if any).
    fn ioctl(
        &mut self,
        path: &str,
        cmd: u32,
        arg: u64,
        fi: &mut FuseFileInfo,
        flags: u32,
        data: Option<Vec<u8>>,
    ) -> Result<IoctlResult, FuseError> {
        let _ = (path, cmd, arg, fi, flags, data);
        Err(FuseError::NotImplemented)
    }

    /// Poll for I/O readiness. Returns the revents bitmask.
    /// `poll_handle` is `Some` when the filesystem should retain the
    /// handle and notify later via `fuse_lowlevel_notify_poll()`.
    fn poll(
        &mut self,
        path: &str,
        fi: &mut FuseFileInfo,
        poll_handle: Option<PollHandle>,
    ) -> Result<u32, FuseError> {
        let _ = (path, fi, poll_handle);
        Err(FuseError::NotImplemented)
    }

    /// Write data supplied in a generic buffer. Returns bytes written.
    fn write_buf(
        &mut self,
        path: &str,
        buf: &FuseBufvec,
        offset: i64,
        fi: &mut FuseFileInfo,
    ) -> Result<usize, FuseError> {
        let _ = (path, buf, offset, fi);
        Err(FuseError::NotImplemented)
    }

    /// Read data into a generic buffer (allocated by the filesystem).
    fn read_buf(
        &mut self,
        path: &str,
        size: usize,
        offset: i64,
        fi: &mut FuseFileInfo,
    ) -> Result<FuseBufvec, FuseError> {
        let _ = (path, size, offset, fi);
        Err(FuseError::NotImplemented)
    }

    /// BSD file locking (`flock(2)`).
    fn flock(&mut self, path: &str, fi: &mut FuseFileInfo, op: i32) -> Result<(), FuseError> {
        let _ = (path, fi, op);
        Err(FuseError::NotImplemented)
    }

    /// Preallocate or deallocate space to a file.
    fn fallocate(
        &mut self,
        path: &str,
        mode: i32,
        offset: i64,
        length: i64,
        fi: &mut FuseFileInfo,
    ) -> Result<(), FuseError> {
        let _ = (path, mode, offset, length, fi);
        Err(FuseError::NotImplemented)
    }

    /// Copy a range of data between two open files. Returns bytes copied.
    #[allow(clippy::too_many_arguments)]
    fn copy_file_range(
        &mut self,
        path_in: &str,
        fi_in: &mut FuseFileInfo,
        offset_in: i64,
        path_out: &str,
        fi_out: &mut FuseFileInfo,
        offset_out: i64,
        size: usize,
        flags: i32,
    ) -> Result<usize, FuseError> {
        let _ = (path_in, fi_in, offset_in, path_out, fi_out, offset_out, size, flags);
        Err(FuseError::NotImplemented)
    }

    /// Seek within a file (`SEEK_DATA` / `SEEK_HOLE`). Returns the
    /// resulting offset.
    fn lseek(
        &mut self,
        path: &str,
        offset: i64,
        whence: i32,
        fi: &mut FuseFileInfo,
    ) -> Result<i64, FuseError> {
        let _ = (path, offset, whence, fi);
        Err(FuseError::NotImplemented)
    }

    /// Extended file attributes (`statx(2)`).
    fn statx(
        &mut self,
        path: &str,
        flags: i32,
        mask: i32,
        stx: &mut Statx,
        fi: Option<&mut FuseFileInfo>,
    ) -> Result<(), FuseError> {
        let _ = (path, flags, mask, stx, fi);
        Err(FuseError::NotImplemented)
    }

    /// Synchronize the whole filesystem (`syncfs(2)`).
    fn syncfs(&mut self, path: &str) -> Result<(), FuseError> {
        let _ = path;
        Err(FuseError::NotImplemented)
    }
}

