// ===========================================================================
// Section: src/types/daemonize.rs — Daemonize types (hand-written, from fuse_daemonize.h)
// ===========================================================================

// Daemonize helpers from `fuse_daemonize.h` and mount flags from
// `fuse_mount_compat.h`.


/// Flags for `fuse_daemonize_early_start()` (`FUSE_DAEMONIZE_*`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
pub struct FuseDaemonizeFlags(pub u32);

impl FuseDaemonizeFlags {
    /// No flags.
    pub const NONE: Self = Self(0);
    /// Do not change directory.
    pub const NO_CHDIR: Self = Self(1 << 0);
    /// Do not go into the background.
    pub const NO_BACKGROUND: Self = Self(1 << 1);

    /// True if all bits of `other` are set.
    pub fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

impl BitOr for FuseDaemonizeFlags {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        Self(self.0 | rhs.0)
    }
}

impl BitAnd for FuseDaemonizeFlags {
    type Output = Self;
    fn bitand(self, rhs: Self) -> Self {
        Self(self.0 & rhs.0)
    }
}

impl Default for FuseDaemonizeFlags {
    fn default() -> Self {
        Self::NONE
    }
}

/// The early-daemonize API (`fuse_daemonize_early_*`).
