/// `enum fuse_log_level` — syslog-style log levels.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, JsonSchema)]
#[repr(u32)]
pub enum FuseLogLevel {
    /// System is unusable.
    Emerg = 0,
    /// Action must be taken immediately.
    Alert = 1,
    /// Critical conditions.
    Crit = 2,
    /// Error conditions.
    Err = 3,
    /// Warning conditions.
    Warning = 4,
    /// Normal but significant conditions.
    Notice = 5,
    /// Informational messages.
    Info = 6,
    /// Debug-level messages.
    Debug = 7,
}

/// The log callback (`fuse_log_func_t`), receiving a formatted message.
pub trait LogHandler: Send {
    /// Handle one log message at the given level.
    fn log(&mut self, level: FuseLogLevel, message: &str);
}

// ===========================================================================
// Section: src/types/opt.rs — Option-parsing types (hand-written, from fuse_opt.h)
// ===========================================================================

// Option parsing types from `fuse_opt.h`: argument vectors and
// option templates.
//
// The C processing callback (`fuse_opt_proc_t`, a function pointer)
// is modelled as the [`FuseOptProc`] trait; function pointers
// cannot be serialized, so it is not part of the schema types.


/// Special `key` values passed to the option processing function.
pub mod opt_keys {
    /// Key passed when an option did not match any template.
    pub const OPT: i32 = -1;
    /// Key passed for all non-options.
    pub const NONOPT: i32 = -2;
    /// Special key: keep the option (as if the proc returned 1).
    pub const KEEP: i32 = -3;
    /// Special key: discard the option (as if the proc returned 0).
    pub const DISCARD: i32 = -4;
}

/// `struct fuse_args` — an argument vector (input + output).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseArgs {
    /// Argument count.
    pub argc: i32,
    /// Argument vector (NULL terminated in C).
    pub argv: Vec<String>,
    /// Whether `argv` was allocated by libfuse.
    pub allocated: bool,
}

impl FuseArgs {
    /// Build from an argument list.
    pub fn new(argv: Vec<String>) -> Self {
        let argc = argv.len() as i32;
        Self {
            argc,
            argv,
            allocated: false,
        }
    }
}

/// `struct fuse_opt` — one option template for `fuse_opt_parse()`.
///
/// `offset` is the byte offset of the target variable inside the
/// `data` block passed to `fuse_opt_parse()`; `None` means the
/// template's `value` is passed as `key` to the processing function
/// instead (the C sentinel `-1`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct FuseOpt {
    /// Matching template and optional parameter formatting
    /// (e.g. `"--opt=%s"`, `"-oopt"`).
    pub template: String,
    /// Offset of the variable within `data`, or `None` (C: `-1`).
    pub offset: Option<u64>,
    /// Value to set the variable to, or to pass as `key` to the
    /// processing function. Ignored if the template has a format.
    pub value: i32,
}

/// The option processing callback (`fuse_opt_proc_t`).
///
/// Called when an option did not match any template, when an
/// argument is a non-option, or when an option matched with offset
/// `-1`. Returns `Ok(true)` to keep the argument, `Ok(false)` to
/// discard it, `Err(_)` on error (C: `-1`).
pub trait FuseOptProc: Send {
    /// Process one argument. `key` is one of [`opt_keys`] (or the
    /// `value` of the matching template).
    fn process(&mut self, arg: &str, key: i32, outargs: &mut FuseArgs) -> Result<bool, FuseError>;
}

