/// Parsed `fuse_conn_info` command-line options
/// (`struct fuse_conn_info_opts`).
///
/// Only the options the user explicitly set are `Some`; the rest are
/// left untouched when applied.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct ConnInfoOpts {
    /// `-o max_write=N`.
    pub max_write: Option<u32>,
    /// `-o max_read=N`.
    pub max_read: Option<u32>,
    /// `-o max_readahead=N`.
    pub max_readahead: Option<u32>,
    /// `-o max_background=N`.
    pub max_background: Option<u32>,
    /// `-o congestion_threshold=N`.
    pub congestion_threshold: Option<u32>,
    /// `-o time_gran=N`.
    pub time_gran: Option<u32>,
    /// Capability bits to set in `want_ext` (from `async_read`,
    /// `atomic_o_trunc`, `splice_write`, ... options).
    pub want_set: Vec<u64>,
    /// Capability bits to clear in `want_ext` (from `sync_read`,
    /// `no_remote_lock`, `readdirplus=no`, ... options).
    pub want_clear: Vec<u64>,
}

impl ConnInfoOpts {
    /// Apply the parsed options to a [`FuseConnInfo`].
    pub fn apply(&self, conn: &mut FuseConnInfo) {
        if let Some(v) = self.max_write {
            conn.max_write = v;
        }
        if let Some(v) = self.max_read {
            conn.max_read = v;
        }
        if let Some(v) = self.max_readahead {
            conn.max_readahead = v;
        }
        if let Some(v) = self.max_background {
            conn.max_background = v;
        }
        if let Some(v) = self.congestion_threshold {
            conn.congestion_threshold = v;
        }
        if let Some(v) = self.time_gran {
            conn.time_gran = v;
        }
        for b in &self.want_set {
            conn.want_ext |= b;
        }
        for b in &self.want_clear {
            conn.want_ext &= !b;
        }
    }
}

