// ===========================================================================
// Section: src/state.rs — Present-state contract and mount options (hand-written)
// ===========================================================================

// Present-state contract and mount-option types for the fuse plugin.
//
// [`FuseState`] is the single typed present-state/control contract:
// deterministic and offline-reproducible, with no live probes or
// credentials in it. [`FuseMountOptions`] is the typed form of the
// FUSE `-o` mount options — the one place in this crate where values
// travel on the wire as strings, so boolean/integer options use the
// [`StrBool`]/[`StrInt`] coercion newtypes from coerce.


/// Plugin name, as registered in the schema document.
pub const PLUGIN_NAME: &str = "fuse";
/// Plugin version (the crate version).
pub const PLUGIN_VERSION: &str = "0.1.0";
/// Plugin category, following the `cap.<category>.<plugin>…` convention.
pub const PLUGIN_CATEGORY: &str = "storage";
/// Human-readable plugin name.
pub const PLUGIN_DISPLAY_NAME: &str = "GB.Fuse";
/// One-line plugin description.
pub const PLUGIN_DESCRIPTION: &str =
    "FUSE filesystem operations: high-level and low-level callbacks, session lifecycle, and mount options";
/// The libfuse version this crate's types were generated from.
pub const LIBRARY_VERSION: &str = "3.19.0";
/// The libfuse API version (`FUSE_MAKE_VERSION(3, 19)`).
pub const API_VERSION: u32 = 319;
/// The kernel protocol version (`7.46`).
pub const KERNEL_PROTOCOL: &str = "7.46";

/// Lifecycle state of a FUSE mount/session.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum FuseSessionState {
    /// No session exists; nothing is mounted.
    #[default]
    Unmounted,
    /// A session exists and is mounted, but its loop is not running.
    Mounted,
    /// The session loop is running and serving requests.
    Running,
    /// The session loop has exited (the mount is going away).
    Exited,
}

/// Deterministic declared state. No live probe or credential is allowed
/// here; schema generation and blob sealing must produce identical
/// output offline.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.fuse.schema@v1"))]
#[schemars(extend("x-oscal-category" = "storage"))]
#[schemars(extend("x-immutable-paths" = ["software", "library_version", "api_version", "kernel_protocol"]))]
pub struct FuseState {
    /// Software this plugin models.
    pub software: String,
    /// Plugin version.
    pub plugin_version: String,
    /// libfuse library version.
    pub library_version: String,
    /// libfuse API version.
    pub api_version: u32,
    /// Kernel protocol version.
    pub kernel_protocol: String,
    /// Mountpoint, once a filesystem is mounted (`None` until then).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mountpoint: Option<String>,
    /// Filesystem subtype, once a filesystem is mounted (`None` until then).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub subtype: Option<String>,
    /// Lifecycle state of the mount/session.
    pub session_state: FuseSessionState,
    /// Capability flags the filesystem wants from the kernel.
    pub capabilities: FuseCapabilities,
    /// Declared maximum read size, once negotiated (`None` = kernel default).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_read: Option<u32>,
    /// Declared maximum write size, once negotiated (`None` = kernel default).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_write: Option<u32>,
    /// Declared maximum readahead, once negotiated (`None` = kernel default).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_readahead: Option<u32>,
    /// Declared maximum background requests, once negotiated (`None` = kernel default).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_background: Option<u32>,
    /// Declared mount options.
    pub mount_options: FuseMountOptions,
}

impl FuseState {
    /// The declared state: fixed values, no probing. A mountpoint and
    /// negotiated limits appear only once a filesystem is actually
    /// mounted; until then the state describes the unmounted plugin.
    pub fn declared() -> Self {
        Self {
            software: "libfuse".to_string(),
            plugin_version: PLUGIN_VERSION.to_string(),
            library_version: LIBRARY_VERSION.to_string(),
            api_version: API_VERSION,
            kernel_protocol: KERNEL_PROTOCOL.to_string(),
            mountpoint: None,
            subtype: None,
            session_state: FuseSessionState::Unmounted,
            capabilities: FuseCapabilities::NONE,
            max_read: None,
            max_write: None,
            max_readahead: None,
            max_background: None,
            mount_options: FuseMountOptions::default(),
        }
    }
}

/// The kind of a [`FuseMountEvent`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum FuseMountEventKind {
    /// A filesystem was mounted.
    Mounted,
    /// A filesystem was unmounted.
    Unmounted,
    /// A session loop exited.
    Exited,
}

/// A mount/session lifecycle event, published on the plugin's event
/// channel. Events are wakeups only: the complete [`FuseState`] is the
/// authoritative observation, never the event payload.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct FuseMountEvent {
    /// What happened.
    pub kind: FuseMountEventKind,
    /// Mountpoint the event concerns.
    pub mountpoint: String,
}

/// Typed form of the FUSE `-o` mount options.
///
/// Every option value travels on the wire as a string, so boolean and
/// integer options use [`StrBool`]/[`StrInt`]: they deserialize from
/// either a JSON string or a native value and always serialize back
/// to a string, so round-tripping is lossless.
///
/// The `-o` string form is DERIVED from this struct (the struct is the
/// single source of truth): [`FuseMountOptions::to_args`] emits the
/// comma-separated option list, [`FuseMountOptions::from_args`] parses
/// it back. A bare key means true, `key=true` means true,
/// `key=false` means false; integer options always carry `=N`; string
/// options always carry `=V`. Unknown keys, duplicates, bare integer
/// options and malformed values are errors, never ignored.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct FuseMountOptions {
    /// Filesystem name (`fsname=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fsname: Option<String>,
    /// Filesystem subtype (`subtype=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub subtype: Option<String>,
    /// Allow access by other users (`allow_other`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub allow_other: Option<StrBool>,
    /// Allow access by root only (`allow_root`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub allow_root: Option<StrBool>,
    /// Unmount automatically on process exit (`auto_unmount`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub auto_unmount: Option<StrBool>,
    /// The mount is a block device (`blkdev`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub blkdev: Option<StrBool>,
    /// Restrict access to the mounting user (`default_permissions`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub default_permissions: Option<StrBool>,
    /// Allow the kernel to cache file data (`kernel_cache`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub kernel_cache: Option<StrBool>,
    /// Enable auto-caching (`auto_cache`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub auto_cache: Option<StrBool>,
    /// Use direct I/O (`direct_io`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub direct_io: Option<StrBool>,
    /// Allow mounting on a non-empty directory (`nonempty`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub nonempty: Option<StrBool>,
    /// Honor setuid/setgid bits (`suid`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub suid: Option<StrBool>,
    /// Honor device files (`dev`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub dev: Option<StrBool>,
    /// Use asynchronous reads (`async_read`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub async_read: Option<StrBool>,
    /// Use synchronous reads (`sync_read`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub sync_read: Option<StrBool>,
    /// Disable remote locking (`no_remote_lock`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub no_remote_lock: Option<StrBool>,
    /// Support `O_TRUNC` atomically (`atomic_o_trunc`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub atomic_o_trunc: Option<StrBool>,
    /// Use readdirplus (`readdirplus`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub readdirplus: Option<StrBool>,
    /// Remove files directly instead of renaming them (`hard_remove`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub hard_remove: Option<StrBool>,
    /// Use the `st_ino` supplied by the filesystem (`use_ino`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub use_ino: Option<StrBool>,
    /// Use the `st_ino` field in `readdir()` (`readdir_ino`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub readdir_ino: Option<StrBool>,
    /// Allow request interruption (`intr`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub intr: Option<StrBool>,
    /// Don't flush on close of a read-only fd (`no_rofd_flush`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub no_rofd_flush: Option<StrBool>,
    /// Allow parallel direct writes (`parallel_direct_writes`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub parallel_direct_writes: Option<StrBool>,
    /// File creation mask (`umask=…`, octal or decimal string).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub umask: Option<StrInt>,
    /// User id to force (`uid=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub uid: Option<StrInt>,
    /// Group id to force (`gid=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub gid: Option<StrInt>,
    /// Maximum read size (`max_read=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub max_read: Option<StrInt>,
    /// Maximum write size (`max_write=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub max_write: Option<StrInt>,
    /// Maximum readahead (`max_readahead=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub max_readahead: Option<StrInt>,
    /// Maximum background requests (`max_background=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub max_background: Option<StrInt>,
    /// Congestion threshold (`congestion_threshold=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub congestion_threshold: Option<StrInt>,
    /// Timestamp granularity (`time_gran=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub time_gran: Option<StrInt>,
    /// Signal to send on interrupt (`intr_signal=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub intr_signal: Option<StrInt>,
    /// Remember inodes after removal, in seconds (`remember=…`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[schemars(with = "Option<String>")]
    pub remember: Option<StrInt>,
}

impl FuseMountOptions {
    /// Serialize to the `-o` option value: comma-separated
    /// `key[=value]` pairs in struct field order. Empty when no
    /// option is set (the caller then omits `-o` entirely).
    pub fn to_args(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        macro_rules! opt_str {
            ($field:ident, $key:literal) => {
                if let Some(v) = &self.$field {
                    parts.push(format!("{}={}", $key, v));
                }
            };
        }
        macro_rules! opt_bool {
            ($field:ident, $key:literal) => {
                if let Some(v) = &self.$field {
                    if v.0 {
                        parts.push($key.to_string());
                    } else {
                        parts.push(format!("{}=false", $key));
                    }
                }
            };
        }
        macro_rules! opt_int {
            ($field:ident, $key:literal) => {
                if let Some(v) = &self.$field {
                    parts.push(format!("{}={}", $key, v.0));
                }
            };
        }
        opt_str!(fsname, "fsname");
        opt_str!(subtype, "subtype");
        opt_bool!(allow_other, "allow_other");
        opt_bool!(allow_root, "allow_root");
        opt_bool!(auto_unmount, "auto_unmount");
        opt_bool!(blkdev, "blkdev");
        opt_bool!(default_permissions, "default_permissions");
        opt_bool!(kernel_cache, "kernel_cache");
        opt_bool!(auto_cache, "auto_cache");
        opt_bool!(direct_io, "direct_io");
        opt_bool!(nonempty, "nonempty");
        opt_bool!(suid, "suid");
        opt_bool!(dev, "dev");
        opt_bool!(async_read, "async_read");
        opt_bool!(sync_read, "sync_read");
        opt_bool!(no_remote_lock, "no_remote_lock");
        opt_bool!(atomic_o_trunc, "atomic_o_trunc");
        opt_bool!(readdirplus, "readdirplus");
        opt_bool!(hard_remove, "hard_remove");
        opt_bool!(use_ino, "use_ino");
        opt_bool!(readdir_ino, "readdir_ino");
        opt_bool!(intr, "intr");
        opt_bool!(no_rofd_flush, "no_rofd_flush");
        opt_bool!(parallel_direct_writes, "parallel_direct_writes");
        opt_int!(umask, "umask");
        opt_int!(uid, "uid");
        opt_int!(gid, "gid");
        opt_int!(max_read, "max_read");
        opt_int!(max_write, "max_write");
        opt_int!(max_readahead, "max_readahead");
        opt_int!(max_background, "max_background");
        opt_int!(congestion_threshold, "congestion_threshold");
        opt_int!(time_gran, "time_gran");
        opt_int!(intr_signal, "intr_signal");
        opt_int!(remember, "remember");
        parts.join(",")
    }

    /// Parse a `-o` option value back into the typed form. Fails
    /// closed: unknown keys, duplicate keys, empty segments, bare
    /// integer/string options and malformed values are all errors.
    pub fn from_args(args: &str) -> Result<Self, FuseError> {
        let mut out = Self::default();
        if args.is_empty() {
            return Ok(out);
        }
        let mut seen: Vec<&str> = Vec::new();
        for segment in args.split(',') {
            if segment.is_empty() || segment.chars().any(char::is_whitespace) {
                return Err(FuseError::InvalidArgument(format!(
                    "malformed mount option segment: {segment:?}"
                )));
            }
            let (key, value) = match segment.split_once('=') {
                Some((k, v)) => (k, Some(v)),
                None => (segment, None),
            };
            if key.is_empty() || seen.contains(&key) {
                return Err(FuseError::InvalidArgument(format!(
                    "duplicate or empty mount option key: {key:?}"
                )));
            }
            seen.push(key);
            let parse_bool = |value: Option<&str>| -> Result<StrBool, FuseError> {
                match value {
                    None => Ok(StrBool(true)),
                    Some("true") | Some("1") => Ok(StrBool(true)),
                    Some("false") | Some("0") => Ok(StrBool(false)),
                    Some(other) => Err(FuseError::InvalidArgument(format!(
                        "invalid boolean mount option value: {other:?}"
                    ))),
                }
            };
            let parse_int = |value: Option<&str>| -> Result<StrInt, FuseError> {
                match value {
                    Some(v) => v
                        .parse::<i64>()
                        .map(StrInt)
                        .map_err(|_| {
                            FuseError::InvalidArgument(format!(
                                "invalid integer mount option value: {v:?}"
                            ))
                        }),
                    None => Err(FuseError::InvalidArgument(
                        "integer mount option requires a value".to_string(),
                    )),
                }
            };
            let parse_str = |value: Option<&str>| -> Result<String, FuseError> {
                match value {
                    Some(v) if !v.is_empty() => Ok(v.to_string()),
                    _ => Err(FuseError::InvalidArgument(
                        "string mount option requires a non-empty value".to_string(),
                    )),
                }
            };
            macro_rules! set_bool {
                ($field:ident, $key:literal) => {
                    if key == $key {
                        out.$field = Some(parse_bool(value)?);
                        continue;
                    }
                };
            }
            macro_rules! set_int {
                ($field:ident, $key:literal) => {
                    if key == $key {
                        out.$field = Some(parse_int(value)?);
                        continue;
                    }
                };
            }
            macro_rules! set_str {
                ($field:ident, $key:literal) => {
                    if key == $key {
                        out.$field = Some(parse_str(value)?);
                        continue;
                    }
                };
            }
            set_str!(fsname, "fsname");
            set_str!(subtype, "subtype");
            set_bool!(allow_other, "allow_other");
            set_bool!(allow_root, "allow_root");
            set_bool!(auto_unmount, "auto_unmount");
            set_bool!(blkdev, "blkdev");
            set_bool!(default_permissions, "default_permissions");
            set_bool!(kernel_cache, "kernel_cache");
            set_bool!(auto_cache, "auto_cache");
            set_bool!(direct_io, "direct_io");
            set_bool!(nonempty, "nonempty");
            set_bool!(suid, "suid");
            set_bool!(dev, "dev");
            set_bool!(async_read, "async_read");
            set_bool!(sync_read, "sync_read");
            set_bool!(no_remote_lock, "no_remote_lock");
            set_bool!(atomic_o_trunc, "atomic_o_trunc");
            set_bool!(readdirplus, "readdirplus");
            set_bool!(hard_remove, "hard_remove");
            set_bool!(use_ino, "use_ino");
            set_bool!(readdir_ino, "readdir_ino");
            set_bool!(intr, "intr");
            set_bool!(no_rofd_flush, "no_rofd_flush");
            set_bool!(parallel_direct_writes, "parallel_direct_writes");
            set_int!(umask, "umask");
            set_int!(uid, "uid");
            set_int!(gid, "gid");
            set_int!(max_read, "max_read");
            set_int!(max_write, "max_write");
            set_int!(max_readahead, "max_readahead");
            set_int!(max_background, "max_background");
            set_int!(congestion_threshold, "congestion_threshold");
            set_int!(time_gran, "time_gran");
            set_int!(intr_signal, "intr_signal");
            set_int!(remember, "remember");
            return Err(FuseError::InvalidArgument(format!(
                "unknown mount option: {key:?}"
            )));
        }
        Ok(out)
    }
}

#[cfg(test)]
mod state_tests {
    use super::*;

    #[test]
    fn mount_options_round_trip_through_args_string() {
        let opts = FuseMountOptions {
            fsname: Some("3tched".to_string()),
            subtype: Some("identity".to_string()),
            allow_other: Some(StrBool(true)),
            default_permissions: Some(StrBool(false)),
            max_readahead: Some(StrInt(131072)),
            uid: Some(StrInt(1000)),
            ..Default::default()
        };
        let args = opts.to_args();
        assert_eq!(
            args,
            "fsname=3tched,subtype=identity,allow_other,default_permissions=false,uid=1000,max_readahead=131072"
        );
        let back = FuseMountOptions::from_args(&args).unwrap();
        assert_eq!(back, opts);
        assert_eq!(FuseMountOptions::from_args("").unwrap(), FuseMountOptions::default());
        assert_eq!(FuseMountOptions::default().to_args(), "");
    }

    #[test]
    fn mount_options_parse_fails_closed() {
        for bad in [
            "allow_other,allow_other", // duplicate
            "bogus_option",            // unknown key
            "max_read",                // bare integer option
            "fsname",                  // bare string option
            "max_read=abc",            // malformed integer
            "allow_other=maybe",       // malformed boolean
            "allow_other,",            // empty segment
            ",allow_other",            // empty segment
            "allow_other, max_read=1", // whitespace
        ] {
            assert!(
                FuseMountOptions::from_args(bad).is_err(),
                "{bad:?} must fail closed"
            );
        }
        // Explicit false round-trips through the struct form.
        assert_eq!(
            FuseMountOptions::from_args("allow_other=false").unwrap().allow_other,
            Some(StrBool(false))
        );
    }

    #[test]
    fn declared_state_is_deterministic_and_offline() {
        let first = FuseState::declared();
        let second = FuseState::declared();
        assert_eq!(first, second);
        assert_eq!(first.session_state, FuseSessionState::Unmounted);
        assert_eq!(first.mountpoint, None);
        assert_eq!(first.software, "libfuse");
        let encoded = serde_json::to_string(&first).unwrap();
        assert!(!encoded.contains("password"));
        assert!(!encoded.contains("credential"));
    }
}

// ===========================================================================
// Section: src/state_plugin.rs — PluginSchema + FS projection extras
// ===========================================================================
//
// libfuse ops/state (above) are the schema foundation. FS-only surface grafted
// here: get_protocol / get_contract / get_receipt + invocation convention.
// No tched* plugin name — sealed as `fuse`.

/// Signal name for mount/session lifecycle events.
pub const MOUNT_EVENT_SIGNAL: &str = "mount_event";
/// Subid for the mount/session lifecycle event signal.
pub const MOUNT_EVENT_SUBID: &str = "evt.storage.fuse.mount-event@v1";

const READ_PROTOCOL: &str = "cap.storage.fuse.protocol.read@v1";
const READ_CONTRACT: &str = "cap.storage.fuse.contract.read@v1";
const READ_RECEIPT: &str = "cap.storage.fuse.receipt.read@v1";

/// Public discovery metadata for the immutable filesystem contract document.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ContractDescriptor {
    pub schema_version: String,
    pub source_commit: String,
    pub method: String,
}

/// Exact sealed filesystem contract document (projection rules, not libfuse ABI).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(transparent)]
pub struct FilesystemContract(serde_json::Value);

impl FilesystemContract {
    pub fn get() -> Self {
        Self(_3tched_fs_contract::document())
    }
}

impl JsonSchema for FilesystemContract {
    fn schema_name() -> std::borrow::Cow<'static, str> {
        "FilesystemContract".into()
    }

    fn json_schema(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
        // Seal the contract itself via schemars — same pattern as the old
        // FS plugin: open object for $defs transport + exact literal allOf.
        serde_json::json!({
            "type": "object",
            "additionalProperties": true,
            "allOf": [literal_contract_schema(&_3tched_fs_contract::document())],
        })
        .try_into()
        .expect("filesystem contract schema is an object")
    }
}

/// Order-independent exact JSON value schema for the sealed contract document.
fn literal_contract_schema(value: &serde_json::Value) -> serde_json::Value {
    use serde_json::{Value, json};
    match value {
        Value::Object(fields) => {
            let properties: serde_json::Map<String, Value> = fields
                .iter()
                .map(|(key, value)| (key.clone(), literal_contract_schema(value)))
                .collect();
            json!({
                "type": "object", "properties": properties,
                "required": fields.keys().collect::<Vec<_>>(),
                "additionalProperties": false,
            })
        }
        Value::Array(items) => {
            let mut schema = json!({
                "type": "array", "minItems": items.len(),
                "maxItems": items.len(), "items": false,
            });
            if !items.is_empty() {
                schema["prefixItems"] = items.iter().map(literal_contract_schema).collect();
            }
            schema
        }
        _ => json!({"const": value}),
    }
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetContractOutput {
    pub contract: FilesystemContract,
}

/// Shared call-file invocation convention relative to the mount.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Invocation {
    pub path: String,
    pub open: String,
    pub arguments: String,
    pub commit: String,
    pub result: String,
    pub declaration: String,
    pub automatic_retry: bool,
}

/// FS projection protocol (not part of libfuse).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
#[schemars(extend("x-oscal-subid" = "sch.storage.fuse.protocol.schema@v1"))]
#[schemars(extend("x-oscal-category" = "storage"))]
pub struct FilesystemProtocol {
    pub filesystem_type: String,
    pub mount_metadata: String,
    pub invocation: Invocation,
    pub contract: ContractDescriptor,
}

impl Default for FilesystemProtocol {
    fn default() -> Self {
        Self {
            filesystem_type: "fuse".into(),
            mount_metadata: ".fuse.json".into(),
            invocation: Invocation {
                path: "plugins/{plugin}/operations/{method}/call".into(),
                open: "O_RDWR".into(),
                arguments: "application/json".into(),
                commit: "fsync".into(),
                result: "seek(0), read receipt or diagnostic on the same descriptor".into(),
                declaration: "plugins/{plugin}/operations/{method}/metadata.json".into(),
                automatic_retry: false,
            },
            contract: ContractDescriptor {
                schema_version: _3tched_fs_contract::schema_version().into(),
                source_commit: _3tched_fs_contract::source_commit().into(),
                method: "get_contract".into(),
            },
        }
    }
}

#[derive(Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetProtocolInput {}

#[derive(Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetContractInput {}

fn add_method<I, O>(
    schema: &mut PluginSchema,
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    capability: &str,
    subid: &str,
) where
    I: JsonSchema,
    O: JsonSchema,
{
    schema.methods.insert(
        name.to_string(),
        method_decl_from_schemars_with_output::<I, O>(
            name,
            side_effect,
            idempotent,
            capability,
            subid,
        ),
    );
    schema.capabilities.insert(
        capability.to_string(),
        CapabilityDecl {
            id: capability.to_string(),
            description: format!("Grants: {name}."),
        },
    );
}

fn register_fs_projection_methods(schema: &mut PluginSchema) {
    add_method::<GetProtocolInput, FilesystemProtocol>(
        schema,
        "get_protocol",
        SideEffect::Read,
        true,
        READ_PROTOCOL,
        "obs.storage.fuse.protocol.get@v1",
    );
    add_method::<GetContractInput, GetContractOutput>(
        schema,
        "get_contract",
        SideEffect::Read,
        true,
        READ_CONTRACT,
        "obs.storage.fuse.contract.get@v1",
    );
    add_method::<
        op_state_store::method_receipt::GetMethodReceiptInput,
        op_state_store::method_receipt::MethodReceiptRecovery,
    >(
        schema,
        "get_receipt",
        SideEffect::Read,
        true,
        READ_RECEIPT,
        "obs.storage.fuse.receipt.get@v1",
    );
    schema.capabilities.insert(
        READ_PROTOCOL.to_string(),
        CapabilityDecl {
            id: READ_PROTOCOL.to_string(),
            description: "Read the shared fuse invocation convention; grants no target operation access."
                .into(),
        },
    );
    schema.capabilities.insert(
        READ_CONTRACT.to_string(),
        CapabilityDecl {
            id: READ_CONTRACT.to_string(),
            description: "Read the immutable typed filesystem contract; grants no mount or backing-store access."
                .into(),
        },
    );
    schema.capabilities.insert(
        READ_RECEIPT.to_string(),
        CapabilityDecl {
            id: READ_RECEIPT.to_string(),
            description: "Recover an operation proof only for the verified caller and session."
                .into(),
        },
    );
}

/// Build the sealed `fuse` PluginSchema: libfuse foundation + FS projection methods.
pub fn fuse_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(FuseState))
        .expect("fuse state schema serializes");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME,
        PLUGIN_VERSION,
        PLUGIN_DESCRIPTION,
        &root,
    );
    schema.category = PLUGIN_CATEGORY.to_string();
    schema.display_name = Some(PLUGIN_DISPLAY_NAME.to_string());
    schema.tags = vec!["immutable".into(), "filesystem".into(), "libfuse".into()];
    let declared = simd_json::serde::to_owned_value(FuseState::declared())
        .expect("declared fuse state serializes");
    super::schemars_adapter::apply_state_defaults(&mut schema, &declared);
    schema.example = Some(declared);
    schema.signals.push(SignalDecl {
        name: MOUNT_EVENT_SIGNAL.to_string(),
        payload: Some(
            simd_json::serde::to_owned_value(schemars::schema_for!(FuseMountEvent))
                .expect("mount event schema serializes"),
        ),
        subid: MOUNT_EVENT_SUBID.to_string(),
    });
    schema.public_state.paths = vec![
        "/session_state".into(),
        "/capabilities".into(),
        "/library_version".into(),
        "/api_version".into(),
        "/kernel_protocol".into(),
    ];
    register_methods(&mut schema);
    // Filesystem contract methods belong to `_3tched_fs`, not this libfuse plugin.
    schema
}

/// Pretty JSON of the sealed schema document (deterministic).
pub fn fuse_schema_json() -> String {
    serde_json::to_string_pretty(&fuse_schema()).expect("fuse schema serializes")
}

/// Plugin object (libfuse schema + FS projection discovery).
pub struct FusePlugin;

impl FusePlugin {
    pub fn new() -> Self {
        Self
    }

    pub fn current_state() -> FuseState {
        FuseState::declared()
    }
}

impl Default for FusePlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for FusePlugin {
    fn name(&self) -> &str {
        PLUGIN_NAME
    }

    fn version(&self) -> &str {
        PLUGIN_VERSION
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(fuse_schema())
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: PLUGIN_NAME.to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let declared = simd_json::serde::to_owned_value(FuseState::declared())?;
        Ok(&declared == desired)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: format!("{PLUGIN_NAME}-checkpoint"),
            plugin: PLUGIN_NAME.to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(FuseState::declared())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Dispatch FS projection discovery methods (libfuse ops stay on trait dispatch).
pub fn dispatch_fs_projection(method: &str, arguments: &serde_json::Value) -> Result<serde_json::Value> {
    match method {
        "get_protocol" => {
            let _: GetProtocolInput = serde_json::from_value(arguments.clone())?;
            Ok(serde_json::to_value(FilesystemProtocol::default())?)
        }
        "get_contract" => {
            let _: GetContractInput = serde_json::from_value(arguments.clone())?;
            Ok(serde_json::to_value(GetContractOutput {
                contract: FilesystemContract::get(),
            })?)
        }
        other => bail!("unknown fuse projection method: {other}"),
    }
}

inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| Arc::new(FusePlugin::new()))
}
